    "人哋": ["呢個係人哋嘅，唔好拎。","That's someone else's, don't take it."],
    "我嘅": ["呢本書係我嘅。","This book is mine."],
    "你嘅": ["呢部手機係唔係你嘅呀？","Is this phone yours?"],
    "佢嘅": ["嗰件衫係佢嘅。","That top is hers."],
    "我哋嘅": ["呢個係我哋嘅老師。","This is our teacher."],
    "你哋嘅": ["你哋嘅屋企好靚。","Your home is lovely."],
    "佢哋嘅": ["佢哋嘅狗好得意。","Their dog is so cute."],
    "呢個": ["我要呢個。","I'll take this one."],
    "嗰個": ["嗰個係邊個呀？","Who is that?"],
    "呢啲": ["呢啲幾多錢呀？","How much are these?"],
    "嗰啲": ["我想要嗰啲。","I'd like those."],
    "呢度": ["呢度好靜。","It's quiet here."],
    "嗰度": ["我喺嗰度等你。","I'll wait for you there."],
    "邊度": ["洗手間喺邊度呀？","Where's the restroom?"],
    "邊個": ["佢係邊個呀？","Who is he?"],
    "咩嘢": ["你食咗咩嘢呀？","What did you eat?"],
    "邊啲": ["你想要邊啲呀？","Which ones do you want?"],
    "人人": ["人人都鍾意佢。","Everybody likes him."],
    "個個": ["個個都好開心。","Everyone is really happy."],
    "有人": ["出面有人搵你。","Someone outside is looking for you."],
    "冇人": ["冇人知。","Nobody knows."],
    "咩都": ["我咩都食。","I eat anything."],
    "邊個都": ["邊個都可以。","Anyone can."],
    "同": ["我同朋友去飲茶。","I'm going for dim sum with friends."],
    "畀": ["唔該畀杯水我。","A glass of water for me, please."],
    "幫": ["你可唔可以幫我呀？","Could you help me?"],
    "用": ["你識唔識用筷子呀？","Can you use chopsticks?"],
    "對": ["佢對我好好。","He's really good to me."],
    "經": ["呢架巴士經唔經旺角呀？","Does this bus go via Mong Kok?"],
    "上面": ["本書喺枱上面。","The book is on the table."],
    "下面": ["隻貓喺床下面。","The cat is under the bed."],
    "入面": ["佢喺房入面。","She's in her room."],
    "出面": ["我喺出面等你。","I'll wait for you outside."],
    "前面": ["地鐵站喺前面。","The MTR station is up ahead."],
    "後面": ["洗手間喺後面。","The restroom is at the back."],
    "隔籬": ["銀行喺超市隔籬。","The bank is next to the supermarket."],
    "對面": ["我住喺公園對面。","I live across from the park."],
    "中間": ["佢坐喺中間。","She's sitting in the middle."],
    "附近": ["附近有冇餐廳呀？","Is there a restaurant nearby?"],
    "樓上": ["我住喺樓上。","I live upstairs."],
    "度": ["嚟我度食飯吖！","Come over to my place for dinner!"],
    "喺度": ["佢唔喺度。","He's not here."],
    "同埋": ["我要一個菠蘿包同埋一杯奶茶。","I'll have a pineapple bun and a milk tea."],
    "但係": ["我想去，但係我冇時間。","I want to go, but I don't have time."],
    "不過": ["好靚，不過好貴。","It's lovely, but it's expensive."],
    "因為": ["我唔去，因為我好攰。","I'm not going because I'm tired."],
    "所以": ["落雨，所以我搭的士。","It's raining, so I'm taking a taxi."],
    "如果": ["如果落雨，我就唔去。","If it rains, I won't go."],
    "或者": ["我哋聽日或者後日去。","We'll go tomorrow or the day after."],
    "定係": ["你要茶定係咖啡呀？","Do you want tea or coffee?"],
